def run(name):
    d = OUT / name; d.mkdir(parents=True, exist_ok=True)
    for f, body in JOBS[name].items(): (d / f).write_text(body)
    s = time.time()
    p = subprocess.run(["timeout", "1800", binary, "-q", "--no-rc", "input.sing"], cwd=d, capture_output=True, text=True)
    (d / "out.log").write_text(p.stdout + p.stderr)
